import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2022-08-16","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2022-08-16","date":"2022-08-16T00:00:00.000Z","updated":"2022-10-21T00:00:00.000Z","tags":["Ceph","distributed storage","CRUSH algorithm","high availability","scalability","object storage","block storage","file system storage","consistency","decentralization","performance","bluestore","bluefs","rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","authentication","authorization","encryption","erasure coding","replication","snapshots","clones","thin provisioning","iSCSI","Fibre Channel","NFS","CIFS","POSIX","monitoring","dashboard","management","orchestration","automation","integration","containerization","Kubernetes","Docker","virtualization","cloud computing","AWS","Azure","Google Cloud","hybrid cloud","multi","cloud","storage cluster","node","disk","SSD","HDD","JBOD","SAN","NAS","network","topology","failure domain","recovery","resilience","load balancing","caching","compression","deduplication","tiering","performance tuning","benchmarking","testing","validation"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-08-16.md","filePath":"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-08-16.md","lastUpdated":1780460162000}'),n={name:"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-08-16.md"};function r(l,e,s,c,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<p>在 2022 年 8 月 16 日的 Ceph Crimson/SeaStore 会议中，团队讨论了一系列技术议题和后续行动计划。以下是对会议内容的总结：</p><h3 id="会议主要内容" tabindex="-1">会议主要内容： <a class="header-anchor" href="#会议主要内容" aria-label="Permalink to &quot;会议主要内容：&quot;">​</a></h3><ol><li><p><strong>OSD Map 共享优化</strong>：讨论了创建外部指针模拟以高效共享 OSD Maps 的解决方案，并进行了多核处理优化。</p></li><li><p><strong>GNS 补丁更新</strong>：Aaron 提交了 GNS 补丁的第二版，解决了评审意见，并讨论了 <code>advance</code> 函数的使用和命名问题。</p></li><li><p><strong>ZNS 测试进展</strong>：Aaron 报告了在物理 ZNS 驱动上的测试情况，并计划进行更长时间的测试。</p></li><li><p><strong>事务管理器优化</strong>：讨论了事务管理器中的特定机制，包括设备清除和异步清理接口的优化。</p></li><li><p><strong>Key Range Remove 和 Omap 合并策略</strong>：讨论了 Key Range Remove 的复杂性，并找到了更好的 Omap 合并策略。</p></li><li><p><strong>测试环境更新</strong>：报告了测试环境中的进展，目前 60% 的测试已通过，正在解决系统挂起的问题。</p></li><li><p><strong>其他更新</strong>：讨论了 Fish Bay Tree 代码的优化，并提交了两个 PR 以修复发现的次要问题。</p></li></ol><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ul><li>Aaron 将发送邮件给 Seth 和 David Galloway，请求更新 CI 机器上的内核版本以支持 ZNS。</li><li>确定 <code>advance</code> 函数的使用和命名问题，将其分为两个调用：<code>advance</code> 和 <code>write</code>。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>Aaron 将继续进行 ZNS 的长时间测试。</li><li>继续优化事务管理器和异步清理接口。</li><li>完成 Key Range Remove 和 Omap 合并策略的改进。</li><li>解决测试环境中的系统挂起问题，并完成剩余的测试。</li></ul><p>会议在讨论了所有议题后结束，所有参会人员祝大家一周愉快。</p>',8)])])}const h=o(n,[["render",r]]);export{S as __pageData,h as default};
